        "t": "61 Keridakacuhan pemerintahan kolonial Belanda selama abad ke-19 disebabkan oleh pandangan ini. Pegawai-pegawai awam Belanda yang sangat terpelajar. para gabenor jenderal dan menteri, mempunyai peranan terhadap ketidakacuhan tersebut. Dalam hal ini, lihat F. de Hann, 1910, Priangan. Batavia: Bataviasch Genootschap van Kunsten cn Wetenschappen. jilid 1, him, 430-31."
