        "t": "62 Dalam hal ini, lihat Proccedings of the Comminee appoinied by His Exceltency the Governor and High Commissioner to inquire into Matters relating to The use of opium in British Malaya Government Printing Office. Singapore. 1924. Pendapatan daripada candu antara tahun 1918 sampai 1922 ialah 30 peratus daripada jumlah pendapatan. (Lampiran XVU, B 19), Candu yang disiapkan ini, 703 ton di antaranya dijual kepada penduduk Cina dewasa yang berjumlah 663 030, dan satu ton kepada 9 043 orang antara 1918-1922. Para penagih candu tentulah bukan main banyak."
