        "t": "hanya memiliki sedikit sahaja baki memenuhi keperluan setelah membayar ufti, maka ia harus menyerahkan hasil kerajinan yang telah dipelajarinya daripada nenek-moyangnya atau daripads orang Cina, Jepun dan suku bangsa lain yang telah menjalin perdagangan dengan masyarakal Filipina sebelum penaklukan, dan membuat hidupnya hanya cukup dengan buah-buahan yang tumbuh berkat, penduduk yang tidak begitu ramai. Begitu banyak ocehan tentang kemalasan masyarukat Filipina,” him. 19."
