        "j": "teks",
        "t": "Latar belakang pembantaian ini adalah permusuhan yang berkembang dan timbulnya saling curiga antara satu sama lain, dari desas-desus yang berbahaya. Dari segi Sejarahnya agak rumit. Meskipun sesudah itu pemerintah Belanda merasa gelisah dengan hal yang tersebut. Valckenier kemudian ditangkap dan diadili, tetapi lebih disebabkan oleh pertentangannya dengan beberapa orang anggota Dewan terhudap kewenangannya, daripada disebabkan oleh pembantaian itu. Orang yang menuduh juga sama-sama bertanggung jawab."
